'use strict';
const t=I18n.t,app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let mains=['attack','shooting','dribbling','passing','physical','general','ball_winning','defense'];
const fields=['full_name','birth_year','position_id','height_cm','strong_foot','country','primary_club','playing_style','weak_foot_usage','weak_foot_accuracy','form','injury_resistance','player_skills','career_clubs'];
const traitLayers={player_skills:'player_skill'};
let state,editing=null,cardPending=null,modalPending=null,previewSequence=0,teamIndex=0,simConfig=null,draftId=null,draftConfidence={},draftSuggested={},draftTouched=new Set(),suggestSequence=0,draftIdentity='';
const player=id=>state.players.find(p=>p.id===id),abilityName=id=>t('ability.'+id),fieldName=id=>t('field.'+id),traitName=id=>t('trait.'+id);
const date=v=>v?new Date(v).toLocaleString(I18n.locale==='he'?'he-IL':'en-GB'):'—';
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';setTimeout(()=>el.style.display='none',6500)}
async function api(path,body){const response=await fetch('/api/'+path,body?{method:'POST',headers:{'Content-Type':'application/json','X-Workbench-Token':state.token},body:JSON.stringify(body)}:{});const data=await response.json();if(!response.ok)throw Error(t(data.code||'error.generic'));return data}
async function reload(full=false){state=await api(!full&&/^#(drafts|abilities|club|country|clubs|countries)(\/|$)/.test(location.hash)?'draft-bootstrap':'bootstrap');if(state.formula){mains=['attack','shooting','dribbling','passing',state.formula.config.mixes.athleticism?'athleticism':'physical','general','ball_winning','defense'];}else if(state.active_main_ratings){mains=state.active_main_ratings;}shell();const old=document.querySelector('#environment-note');if(old)old.remove();if(state.environment==='test')document.querySelector('#header').insertAdjacentHTML('beforeend',`<strong id="environment-note" class="warning">${t('test_environment')}</strong>`)}
function acceptSavedPlayer(p){const i=state.players.findIndex(x=>x.id===p.id);if(i<0)state.players.push(p);else state.players[i]=p;entityDataDirty=true;}
function shell(){document.title=t('brand')+' · '+t('workspace');const nav=[['dashboard','dashboard'],['players','players'],['gk','gk.title'],['clubs','entities.clubs'],['countries','entities.countries'],['abilities','rankings'],['analytics','analytics.title'],];document.querySelector('#sidebar').innerHTML=`<a class="brand" href="#dashboard">${t('brand')}<span>${t('visual.private_collection')}</span></a><div class="workspace">${t('ui.collection')}</div><nav aria-label="${t('ui.collection')}">${UI.Navigation(nav)}</nav><div class="aside-bottom">${t('owner')}<br><small>${(state?.active_v3||state?.formula?.config?.mixes?.athleticism)?t('v3.active'):t('active_engine')}</small></div>`;document.querySelector('#header').innerHTML=`<span>${t('project')}</span><span class="tag">${t('visual.private_collection')}</span>`}
const heading=(key,sub='')=>`<div class="title"><div><h1>${t(key)}</h1>${sub?`<p>${t(sub)}</p>`:''}</div></div>`;
const status=p=>'';
const overall=p=>p.rating?.display_overall??'—';
function ratings(p){return `<div class="ratings">${mains.map(k=>{const v=p.rating?.display_main_ratings?.[k];return `<div class="rating ${UI.MainTier(v)}"><span>${t('main.'+k)}</span><strong>${v??'—'}</strong><progress value="${Math.max(0,Math.min(100,Number(v)||0))}" max="100" aria-label="${t('main.'+k)}"></progress></div>`}).join('')}</div>`}
let portraitPage=1,portraitPageSize=25;
function table(ps){ps=[...ps].sort(location.hash==='#players'?playerListCompare:(a,b)=>compareRatingValues(b.rating?.internal_overall??-1,a.rating?.internal_overall??-1)||a.id.localeCompare(b.id));const total=ps.length,pages=Math.max(1,Math.ceil(total/portraitPageSize));portraitPage=Math.max(1,Math.min(portraitPage,pages));ps=ps.slice((portraitPage-1)*portraitPageSize,portraitPage*portraitPageSize);return UI.DataCard(`<div class="ranking-table-wrap player-directory"><table><thead><tr>${['field.full_name','overall','field.position_id','ui.position_rank','ui.affiliation','ui.skills_count','updated'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>UI.PlayerRow([`<button class="link" data-quick="${p.id}">${UI.Portrait(p.id)}<span class="player-row-name">${esc(p.full_name)}</span></button>`,UI.RatingBadge(overall(p)),UI.PositionChip(p.fields.position_id),p.position_rank?`<span dir="ltr" class="ui-position-rank">#${p.position_rank} ${esc(p.fields.position_id)}</span>`:'—',`<div class="ui-affiliation">${entityLink('club',p.fields.primary_club)}<small>${entityLink('country',p.fields.country)}</small></div>`,`<span title="${t('ui.skills_count')}">${Array.isArray(p.fields.player_skills)?p.fields.player_skills.length:'—'}</span>`,`<small class="ui-row-updated">${date(p.updated_at)}</small>`])).join('')}</tbody></table></div><div class="actions"><button data-portrait-page="${portraitPage-1}" ${portraitPage<=1?'disabled':''}>${t('entities.previous')}</button>${pageJumpHTML(portraitPage,pages,'data-portrait-page')}<button data-portrait-page="${portraitPage+1}" ${portraitPage>=pages?'disabled':''}>${t('entities.next')}</button></div>${!ps.length?UI.EmptyState(t('empty')):''}`)}
function identityFact(k,v){if(k==='height_cm')return (Number(v)/100).toFixed(2);if(k==='strong_foot')return t('ui.foot.'+v);return esc(shown(k,v))}

function pitch(){return Formation.render(state.dashboard.teams[teamIndex],{translate:t,escape:esc,overall})}
let homePosition=null;
function officialRanks(p){return p.overall_rank&&p.position_rank?`<p class="official-ranks">${t('official_ranks',{overall:p.overall_rank,position:p.position_rank,label:t('position.'+p.fields.position_id)})}</p>`:''}
function homePositionList(){const rows=state.dashboard.position_top10[homePosition]||[];return `<div role="tabpanel" id="home-position-results" aria-label="${t('position.'+homePosition)}"><h3>${t('position.'+homePosition)}</h3><div class="position-top-list">${rows.map((p,i)=>`<button class="position-top-row" data-quick="${esc(p.id)}"><span class="position-order">${i+1}</span>${UI.Portrait(p.id)}<span class="position-top-name">${esc(p.full_name)}<small>${esc(p.fields.country||'')} · ${esc(p.fields.primary_club||'')}</small></span>${UI.RatingBadge(overall(p))}</button>`).join('')||UI.EmptyState(t('home_no_position_players'))}</div></div>`}

let homeTeamIndex=0;
function dashboard(){homeTeamIndex=0;const d=state.dashboard;if(!homePosition)homePosition=d.position_order.find(pos=>d.position_top10[pos].length)||'GK';
// Each column uses the existing ranked position list; no new selection or rating calculation.

app.innerHTML=`<div class="home-renewed"><section class="home-hero-new"><div><span class="editorial-kicker">${t('ui.browse')}</span><h1>${t('brand')}</h1><p>${t('ui.hero_sub')}</p></div><div class="home-count-new"><strong>${d.rated_count}</strong><span>${t('visual.rated_players')}</span></div></section><section class="home-first-team"><div class="home-lineup-story"><span class="editorial-kicker">זרקור על המאגר</span><h2>נבחרת האגדות</h2><p>ההרכב הראשון של המאגר · השחקנים שנבחרו לפי הדירוג הקיים</p><div class="ui-chips"><span class="ui-chip" dir="ltr">4-3-3</span><span class="ui-chip">${d.top11.slots.filter(s=>s.player).length} שחקנים</span><span class="ui-chip">כל הזמנים</span></div><div class="home-lineup-stars">${d.top11.slots.filter(s=>s.player).map(s=>s.player).sort((a,b)=>Number(player(b.id)?.rating?.internal_overall??b.rating.display_overall)-Number(player(a.id)?.rating?.internal_overall??a.rating.display_overall)).slice(0,3).map(p=>`<button data-quick="${esc(p.id)}">${UI.Portrait(p.id)}<span>${esc(p.full_name)}<small>${esc(p.fields?.primary_club||'')}</small></span>${UI.RatingBadge(overall(p))}</button>`).join('')}</div><div class="home-lineup-actions"><a href="#players">צפה בשחקנים ←</a><a href="#clubs">מועדונים</a><a href="#countries">נבחרות</a></div></div><div class="home-lineup-preview"><div class="section-heading"><h3>${t('home_top11')}</h3><span class="formation-label">4—3—3</span></div><div id="home-team-pitch">${Formation.preview(d.top11)}</div><div class="home-team-pager" aria-label="בחירת הרכב"><button data-home-team-step="-1" disabled>הקודם</button><span id="home-team-counter" aria-live="polite">הרכב 1 מתוך 10</span><button data-home-team-step="1">הבא</button></div></div></section><section class="home-positions-new"><div class="section-heading"><h2>${t('home_top10_positions')}</h2><a href="#players">${t('visual.all_players')} ←</a></div><label class="mobile-position-select">עמדה<select data-home-position-select>${d.position_order.map(pos=>`<option value="${pos}" ${pos===homePosition?'selected':''}>${t('filter_position.'+pos)}</option>`).join('')}</select></label><div class="position-tabs" role="tablist" aria-label="${t('home_top10_positions')}">${d.position_order.map(pos=>`<button role="tab" aria-selected="${pos===homePosition}" aria-controls="home-position-results" data-home-position="${pos}">${t('filter_position.'+pos)}</button>`).join('')}</div><div id="home-position-host">${homePositionList()}</div></section><section class="home-nav-new"><h2>${t('home.shortcuts')}</h2><div>${[['players','players'],['gk','gk.title'],['clubs','entities.clubs'],['countries','entities.countries'],['abilities','rankings'],['analytics','analytics.title'],].map(([path,key])=>UI.NavigationCard(path,t(key))).join('')}</div></section></div>`}

document.addEventListener('click',e=>{const button=e.target.closest('[data-home-position]');if(button){homePosition=button.dataset.homePosition;document.querySelectorAll('[data-home-position]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.homePosition===homePosition)));document.querySelector('#home-position-host').innerHTML=homePositionList()}});

let playerSort='overall-desc';
function playerListCompare(a,b){
 const rating=()=>compareRatingValues(b.rating?.internal_overall??-1,a.rating?.internal_overall??-1);
 return (playerSort==='name'?a.full_name.localeCompare(b.full_name,'he'):playerSort==='position-rank'?(a.position_rank??9999)-(b.position_rank??9999):playerSort.startsWith('updated')?(playerSort.endsWith('asc')?1:-1)*String(a.updated_at||'').localeCompare(b.updated_at||''):playerSort==='overall-asc'?-rating():rating())||a.id.localeCompare(b.id);
}
function players(){app.innerHTML=heading('players','players_sub')+`<p class="list-summary">${state.players.length} שחקנים · ${new Set(state.players.map(p=>p.fields.position_id)).size} עמדות · עודכן ${UI.ShortDate(state.players.map(p=>p.updated_at||'').sort().at(-1))}</p><div class="filters players-clean-filters">${UI.SearchField({id:'search'})}<label>עמדה<select id="position-filter" aria-label="עמדה"><option value="">כל העמדות</option>${POSITION_ORDER.filter(k=>k in state.catalog.positions).map(k=>`<option value="${k}">${t('position.'+k)}</option>`).join('')}</select></label><label>מיון לפי<select id="player-sort-filter">${[['overall-desc','Overall — גבוה לנמוך'],['overall-asc','Overall — נמוך לגבוה'],['position-rank','דירוג בעמדה'],['updated-desc','עודכן לאחרונה — חדש לישן'],['updated-asc','עודכן לאחרונה — ישן לחדש'],['name','שם']].map(([v,l])=>`<option value="${v}" ${v===playerSort?'selected':''}>${l}</option>`).join('')}</select></label><label>שחקנים בעמוד<select data-portrait-size>${[25,50,100].map(n=>`<option ${n===portraitPageSize?'selected':''}>${n}</option>`).join('')}</select></label></div><div id="player-list">${table(state.players)}</div>`}
function filter(reset=true){if(reset)portraitPage=1;const q=document.querySelector('#search').value.toLowerCase(),pos=document.querySelector('#position-filter').value;playerSort=document.querySelector('#player-sort-filter').value;document.querySelector('#player-list').innerHTML=table(state.players.filter(p=>p.full_name.toLowerCase().includes(q)&&(!pos||p.fields.position_id===pos)))}

function quick(id){if(player(id)?.fields.position_id==='GK'){gkQuick(player(id));return;}modal.dataset.playerId=id;const p=player(id);modal.innerHTML=`<div class="modal-head"><div><h2>${t('quick')}</h2><div class="quick-identity">${UI.Portrait(p.id)}<h1>${esc(p.full_name)}</h1></div>${status(p)}</div><button class="secondary" data-close>${t('close')}</button></div><div class="player-heading"><div class="overall">${overall(p)}</div><p>${esc(shown('position_id',p.fields.position_id))} · ${entityLink('country',p.fields.country)} · ${entityLink('club',p.fields.primary_club)}</p></div>${officialRanks(p)}${playerHonours(p.id)}${ratings(p)}<div class="actions"><button data-quick-edit="${id}">${t('edit')}</button><button data-full="${id}" class="secondary">${t('full_card')}</button></div>`;modal.showModal()}
function shown(k,v){if(v===null||v===undefined)return t('missing');if(k==='position_id')return t('position.'+v);if(k==='strong_foot')return t(v);if(k==='playing_style')return v==='none'?t('none'):traitName(v);if(k in traitLayers)return v.length?v.map(traitName).join(' · '):t('none');return Array.isArray(v)?v.join(' · ')||t('none'):v}
const skillCategories={"dribble": ["scissors_feint", "double_touch", "flip_flap", "marseille_turn", "sombrero", "cross_over_turn", "cut_behind_turn", "scotch_move", "step_on_ball_control", "rabona"], "shooting": ["chip_shot_control", "heading", "long_range_shooting", "long_range_drive", "knuckle_shot", "dipping_shot", "rising_shots", "acrobatic_finishing", "first_time_shot", "penalty_specialist"], "passing": ["heel_trick", "one_touch_pass", "through_passing", "weighted_pass", "pinpoint_crossing", "outside_curler", "no_look_pass", "low_lofted_pass", "long_throw"], "character": ["gamesmanship", "captaincy", "super_sub", "fighting_spirit", "track_back"], "defense": ["man_marking", "interception", "acrobatic_clear"]};
function traitOptions(k,v){
 const catalog=state.traits[traitLayers[k]],choice=x=>`<label class="trait-choice"><input type="checkbox" data-trait="${k}" value="${x.id}" ${v?.includes(x.id)?'checked':''}>${traitName(x.id)}</label>`;
 if(k!=='player_skills')return catalog.map(choice).join('');
 const seen=new Set(),groups=Object.entries(skillCategories).map(([key,ids])=>[key,ids.map(id=>catalog.find(x=>x.id===id)).filter(x=>x&&!seen.has(x.id)&&seen.add(x.id))]);
 groups.push(['other',catalog.filter(x=>!seen.has(x.id))]);
 return groups.filter(([,items])=>items.length).map(([key,items])=>`<fieldset class="skill-category"><legend>${t('skill_category.'+key)}</legend>${items.map(choice).join('')}</fieldset>`).join('');
}
function fieldControl(k,v,meta={}){
 let options=null,control;const range=state.validation.ranges[k];
 if(range)options=Array.from({length:range[1]-range[0]+1},(_,i)=>[i+range[0],i+range[0]]);
 else if(k==='position_id')options=Object.keys(state.catalog.positions).map(id=>[id,t('position.'+id)]);
 else if(k==='strong_foot')options=['left','right','both'].map(id=>[id,t(id)]);
 else if(k==='playing_style')options=[['none',t('none')],...state.traits.playing_style.map(x=>[x.id,traitName(x.id)])];
 if(options)control=`<select name="${k}" aria-label="${fieldName(k)}"><option value="">${t('missing')}</option>${options.map(([id,n])=>`<option value="${id}" ${String(v)===String(id)?'selected':''}>${esc(n)}</option>`).join('')}</select>`;
 else if(k in traitLayers){const limit=state.validation.limits[k];control=`<div class="trait-picker" data-trait-picker="${k}"><div class="trait-counter" data-counter="${k}" aria-live="polite">${t('counter',{count:v?.length||0,max:limit})}</div><div class="trait-options">${traitOptions(k,v)}</div><div class="maximum-note" data-maximum="${k}"></div><label><input type="checkbox" name="known_${k}" ${v!==null&&v!==undefined?'checked':''}>${t('known_list')}</label></div>`}
 else control=`<input name="${k}" aria-label="${fieldName(k)}" ${['height_cm','birth_year'].includes(k)?'type="number" min="1" step="1"':'type="text"'} value="${esc(Array.isArray(v)?v.join(', '):v??'')}" placeholder="${t(k==='career_clubs'?'clubs_hint':'missing')}">`;
 return `<div class="field ${k in traitLayers?'ui-trait-field':''}"><label>${fieldName(k)}</label>${control}${UI.Metadata(meta,v)}${v==null?`<small class="muted">${t('missing')}</small>`:''}</div>`;
}
function updateCounters(root=app){root.querySelectorAll('[data-trait-picker]').forEach(group=>{const key=group.dataset.traitPicker,limit=state.validation.limits[key],boxes=[...group.querySelectorAll('[data-trait]')],count=boxes.filter(b=>b.checked).length;group.querySelector('[data-counter]').textContent=t('counter',{count,max:limit});const compact=root.querySelector(`[data-compact-counter="${key}"]`);if(compact)compact.textContent=t('counter',{count,max:limit});group.querySelector('[data-maximum]').textContent=count>=limit?t('maximum'):'';boxes.forEach(b=>b.disabled=count>=limit&&!b.checked)})}
function readFields(form){const result={};for(const k of fields){if(k in traitLayers){const known=form.elements.namedItem('known_'+k);if(known)result[k]=known.checked?[...form.querySelectorAll(`[data-trait="${k}"]:checked`)].map(x=>x.value):null;continue}const el=form.elements.namedItem(k);if(!el)continue;if(k==='career_clubs')result[k]=el.value.split(',').map(s=>s.trim()).filter(Boolean);else if(k==='height_cm'||k==='birth_year'||k in state.validation.ranges)result[k]=el.value===''?null:Number(el.value);else result[k]=el.value.trim()||null}return result}
function validateFrontend(values){for(const [k,range]of Object.entries(state.validation.ranges)){const v=values[k];if(v!=null&&(!Number.isInteger(v)||v<range[0]||v>range[1]))throw Error(t('validation.'+k))}for(const [k,max]of Object.entries(state.validation.limits)){const v=values[k];if(v!=null&&(!Array.isArray(v)||v.length>max||new Set(v).size!==v.length))throw Error(t('validation.'+k))}if(values.playing_style!=null&&typeof values.playing_style!=='string')throw Error(t('validation.playing_style'))}
function compactSkills(values){const seen=new Set(),groups=Object.entries(skillCategories).map(([key,ids])=>[key,(values||[]).filter(id=>ids.includes(id)&&!seen.has(id)&&seen.add(id))]);groups.push(['other',(values||[]).filter(id=>!seen.has(id))]);return groups.filter(([,ids])=>ids.length).map(([key,ids])=>`<div class="compact-skill-group"><small>${t('skill_category.'+key)}</small>${UI.Chips(ids.map(traitName))}</div>`).join('')||`<span class="muted">${t(values==null?'missing':'none')}</span>`}
function compactTraits(p,edit){return `<section class="panel compact-traits">${UI.SectionHeader(t('ui.traits'))}<div class="compact-trait-columns"><div class="compact-style"><h3>${fieldName('playing_style')}</h3>${edit?fieldControl('playing_style',p.fields.playing_style,p.metadata.playing_style):`<strong>${esc(shown('playing_style',p.fields.playing_style))}</strong>`}</div>${['player_skills'].map(k=>edit?`<details class="compact-trait-editor"><summary>${t('edit')} ${fieldName(k)} <span data-compact-counter="${k}">${t('counter',{count:p.fields[k]?.length||0,max:state.validation.limits[k]})}</span></summary>${fieldControl(k,p.fields[k],p.metadata[k])}</details>`:`<div class="compact-trait-line"><h3>${fieldName(k)}</h3>${k==='player_skills'?compactSkills(p.fields[k]):`<ul class="compact-com-list">${(p.fields[k]||[]).map(id=>`<li>${esc(traitName(id))}</li>`).join('')||`<li>${t(p.fields[k]==null?'missing':'none')}</li>`}</ul>`}</div>`).join('')}</div></section>`}

function card(id,edit=false){edit=false;if(player(id)?.fields.position_id==='GK'){gkPage(player(id).gk.id);return;}cardPending=null;previewSequence++;editing=edit?id:null;const p=player(id);if(!p){app.innerHTML=UI.EmptyState(t('empty'));return}
 const supplemental=['form','weak_foot_usage','weak_foot_accuracy','injury_resistance'];const profile=fields.filter(k=>!['playing_style','player_skills',...supplemental].includes(k));
 const readField=k=>`<div class="field"><label>${fieldName(k)}</label><div>${k==='country'?entityLink('country',p.fields[k]):k==='primary_club'?entityLink('club',p.fields[k]):esc(shown(k,p.fields[k]))}</div></div>`;
 app.innerHTML=`<div class="ui-player-page compact-player"><div class="ui-player-hero"><span class="profile-portrait">${UI.Portrait(p.id)}</span>${UI.RatingBadge(overall(p),{large:true})}<div class="ui-identity"><h1>${esc(p.full_name)}</h1><p><span class="compact-position">${esc(shown('position_id',p.fields.position_id))}</span> ${entityLink('country',p.fields.country)} · ${entityLink('club',p.fields.primary_club)}</p>${officialRanks(p)}${playerHonours(p.id)}${Array.isArray(p.peak_seasons||p.proposal_context?.peak_seasons)?`<small class="muted">עונות שיא: ${esc((p.peak_seasons||p.proposal_context.peak_seasons).slice(0,3).join(" · "))}</small>`:""}<div class="ui-identity-facts">${['height_cm','strong_foot','birth_year'].filter(k=>p.fields[k]!=null).map(k=>`<span>${identityFact(k,p.fields[k])}</span>`).join('')}</div></div><button class="secondary" data-edit="${id}" data-mode="${edit?'view':'edit'}">${t(edit?'view':'edit')}</button></div>${UI.SectionHeader(t('ui.main_ratings'))}${ratings(p)}${p.rating?.status==='pending'?`<div class="warning">${t('missing_calculation')}</div>`:''}<form id="edit-form">${edit?`<div class="ui-card-live" id="card-preview" aria-live="polite"><span>${t('overall')} ${overall(p)}</span><button type="button" data-card-preview="${id}">${t('preview_save')}</button></div>`:''}<section class="panel ui-abilities-panel">${UI.SectionHeader(t('ui.abilities'),'22')} ${UI.GroupedAbilities(k=>k==='form_ability'?formAbilityCard(p,edit):k==='teamwork'?teamworkCard(p,edit):`<div class="ability" data-ability-group="${Object.keys(UI.abilityGroups).find(g=>UI.abilityGroups[g].includes(k))||'general'}"><a href="#abilities/${k}">${abilityName(k)}</a>${edit?`<select class="${UI.AbilityTier(p.abilities[k])}" name="ability_${k}" aria-label="${abilityName(k)}">${state.catalog.allowed_scores.map(v=>`<option ${v===p.abilities[k]?'selected':''}>${v}</option>`).join('')}</select>`:UI.AbilityValue(p.abilities[k])}</div>`)}<div class="compact-supplemental"><h3>${t('ui.supplemental')}</h3><div class="fields">${supplemental.map(k=>edit?fieldControl(k,p.fields[k],p.metadata[k]):readField(k)).join('')}</div></div></section>${compactTraits(p,edit)}<details class="panel compact-profile"><summary>${t('ui.profile')}</summary><div class="fields">${profile.map(k=>edit?fieldControl(k,p.fields[k],p.metadata[k]):readField(k)).join('')}</div></details></form><details class="ui-admin"><summary>${t('ui.information')}</summary><div class="actions"><button type="button" data-propose-player="${id}">${t('create_proposal')}</button><button type="button" data-review-player="${id}">${t('review_suggestions')}</button></div></details><p class="ui-player-updated">${t('updated')}: ${date(p.updated_at)}</p></div>`;updateCounters();UI.enhance()}
function changes(id){const p=player(id),form=document.querySelector('#edit-form'),values=readFields(form),changed={},abilities={};validateFrontend(values);for(const [k,v]of Object.entries(values)){const a=k in traitLayers&&Array.isArray(v)?[...v].sort():v,b=k in traitLayers&&Array.isArray(p.fields[k])?[...p.fields[k]].sort():p.fields[k];if(JSON.stringify(a)!==JSON.stringify(b))changed[k]=v}for(const a of state.catalog.abilities){const v=Number(form.elements.namedItem('ability_'+a.id).value);if(v!==p.abilities[a.id])abilities[a.id]=v}const tw=form.elements.namedItem('card_teamwork');const teamwork=tw&&tw.value!==''&&Number(tw.value)!==p.teamwork?{teamwork:Number(tw.value),teamwork_revision:p.teamwork_revision}:{};const fa=form.elements.namedItem('card_form_ability');const formAbility=fa&&fa.value!==''&&Number(fa.value)!==p.form_ability?{form_ability:Number(fa.value)}:{};return {...formAbility,...teamwork,player_id:id,revision:p.revision,fields:changed,abilities,confirm:[...form.querySelectorAll('[name=confirm]:checked')].map(x=>x.value)}}
function previewHtml(body,r){const p=player(body.player_id);return `<h3>${t('changes')}</h3>${body.teamwork!==undefined?`<p>${t('ability.teamwork')} <b dir="ltr">${p.teamwork??'—'} → ${body.teamwork}</b></p><p>${t('main.general')} <b dir="ltr">${r.old?.final_main_ratings?.general??'—'} → ${r.new.final_main_ratings?.general??'—'}</b></p>`:''}${Object.entries(body.abilities||{}).map(([k,v])=>`<p>${abilityName(k)} <b dir="ltr">${p.abilities[k]} → ${v}</b></p>`).join('')}<p>${t('overall')}: <b dir="ltr">${r.old?.display_overall??'—'} → ${r.new.display_overall??'—'}</b></p><p>${t('internal')}: <span dir="ltr">${r.old?.internal_overall??'—'} → ${r.new.internal_overall??'—'}</span></p>${ratings({rating:r.new})}${r.new.issues?`<div class="warning">${t('missing_calculation')}</div>`:''}`}
function cardLivePreview(body,r){const p=player(body.player_id),num=v=>v==null?'—':UI.Number(v),changed=mains.filter(k=>k!=='general'&&r.old?.final_main_ratings?.[k]!==r.new.final_main_ratings?.[k]);return (body.form_ability!==undefined?UI.DeltaPreview(abilityName('form_ability'),p.form_ability,body.form_ability):'')+Object.entries(body.abilities||{}).map(([k,v])=>UI.DeltaPreview(abilityName(k),p.abilities[k],v)).join('')+(body.teamwork!==undefined?UI.DeltaPreview(abilityName('teamwork'),p.teamwork,body.teamwork):'')+UI.DeltaPreview(t('overall'),num(r.old?.internal_overall),num(r.new.internal_overall))+UI.DeltaPreview(t('main.general'),num(r.old?.final_main_ratings?.general),num(r.new.final_main_ratings?.general))+changed.map(k=>UI.DeltaPreview(t('main.'+k),num(r.old?.final_main_ratings?.[k]),num(r.new.final_main_ratings?.[k]))).join('')+`<details><summary>${t('ui.details')}</summary>${previewHtml(body,r)}</details>`}
async function cardPreview(id){const seq=++previewSequence;cardPending=null;const target=document.querySelector('#card-preview');if(!target)return;target.innerHTML=`<p>${t('loading')}</p>`;try{const body=changes(id),r=await api('preview',body);if(seq!==previewSequence||editing!==id||!target.isConnected)return;cardPending={body,preview_token:r.preview_token};target.innerHTML=cardLivePreview(body,r)+`<button type="button" data-save-card="${id}">${t('save_card')}</button>`}catch(error){if(seq===previewSequence)target.innerHTML=`<p class="warning">${esc(error.message)}</p>`}}
async function modalPreview(body){const r=await api('preview',body);modalPending={...body,preview_token:r.preview_token};modal.innerHTML=`<div class="modal-head"><h2>${t('preview')}</h2><button data-close class="secondary">${t('cancel')}</button></div>${previewHtml(body,r)}<div class="actions"><button data-save>${t('save')}</button><button data-close class="secondary">${t('cancel')}</button></div>`;modal.showModal()}
let abilityPosition='',abilityStyle='';
// Compare stored decimal strings without rounding them to display scores.
function compareRatingValues(a,b){const parts=v=>{let [n,f='']=String(v).split('.');return [n,f]};const [an,af]=parts(a),[bn,bf]=parts(b),length=Math.max(af.length,bf.length);const av=BigInt(an+af.padEnd(length,'0')),bv=BigInt(bn+bf.padEnd(length,'0'));return av>bv?1:av<bv?-1:0}
function abilityRankings(key){key=key||state.catalog.abilities[0].id;const main=key.startsWith('main-'),metric=main?key.slice(5):key,options=main?mains:[...state.catalog.abilities.map(a=>a.id),'teamwork'];if(!options.includes(metric))return;const label=k=>main?t('main.'+k):abilityName(k),value=p=>main?p.rating?.final_main_ratings?.[metric]:(metric==='teamwork'?p.teamwork:p.abilities[metric]);const ps=state.players.filter(p=>p.fields.position_id!=='GK'&&p.rating?.internal_overall!=null&&value(p)!=null&&(!abilityPosition||p.fields.position_id===abilityPosition)&&(!abilityStyle||p.fields.playing_style===abilityStyle)).sort((a,b)=>compareRatingValues(value(b),value(a)));app.innerHTML=`<section class="ranking-page">${heading('rankings','visual.rank_sub')}<div class="ranking-switch"><a href="#abilities/${state.catalog.abilities[0].id}" class="${main?'':'selected'}" ${main?'':'aria-current="page"'}>${t('visual.base_tab')}</a><a href="#abilities/main-attack" class="${main?'selected':''}" ${main?'aria-current="page"':''}>${t('visual.main_tab')}</a></div><div class="panel ranking-controls"><div class="filters"><label>${t('visual.metric')}<select id="ranking-metric">${options.map(k=>`<option value="${main?'main-':''}${k}" ${k===metric?'selected':''}>${label(k)}</option>`).join('')}</select></label><label>${fieldName('position_id')}<select id="ability-position" data-ability-key="${key}"><option value="">${t('all_positions')}</option>${Object.keys(state.catalog.positions).map(id=>`<option value="${id}" ${id===abilityPosition?'selected':''}>${t('filter_position.'+id)}</option>`).join('')}</select></label><label>${fieldName('playing_style')}<select id="ability-style" data-ability-key="${key}"><option value="">${t('all_styles')}</option>${state.traits.playing_style.map(x=>`<option value="${x.id}" ${x.id===abilityStyle?'selected':''}>${traitName(x.id)}</option>`).join('')}</select></label></div><div class="ranking-context"><span>${t('visual.descending')}</span><span>${abilityPosition?t('filter_position.'+abilityPosition):t('all_positions')}</span><span>${abilityStyle?traitName(abilityStyle):t('all_styles')}</span></div></div><div class="panel ranking-results ${main?'main-ranking':'base-ranking'}"><div class="section-heading"><h2>${label(metric)}</h2><span class="result-count">${t('visual.results',{count:ps.length})}</span></div>${main?`<p class="small muted">${t('visual.precise_sort')}</p>`:''}${!ps.length?`<div class="empty"><h3>${t('empty')}</h3><p>${t('visual.empty_filter')}</p></div>`:`<div class="ranking-table-wrap"><table><thead><tr><th>${fieldName('full_name')}</th><th>${t('score')}</th><th>${t('overall')}</th>${main?'':`<th>${t('edit')}</th>`}</tr></thead><tbody>${ps.map(p=>`<tr><td><button class="link" data-quick="${p.id}">${esc(p.full_name)}</button><small class="ranking-player-meta">${esc(shown('position_id',p.fields.position_id))} · ${esc(shown('playing_style',p.fields.playing_style))}</small></td><td class="score">${main?p.rating.display_main_ratings?.[metric]??'—':value(p)}</td><td>${overall(p)}</td>${main?'':`<td><div class="ability-edit-actions"><select id="score-${p.id}" aria-label="${abilityName(key)} ${esc(p.full_name)}">${[...state.catalog.allowed_scores].reverse().map(v=>`<option ${v===(key==='teamwork'?p.teamwork:p.abilities[key])?'selected':''}>${v}</option>`).join('')}</select><button class="secondary" data-ability="${key}" data-id="${p.id}">${t('preview')}</button></div></td>`}</tr>`).join('')}</tbody></table></div>`}</div></section>`}
