function ruleSource(r){const key=r.source.key;return I18n.strings['trait.'+key]||I18n.strings['source.'+key]||I18n.strings['field.'+key]||t('source')}
function rulesTable(config){return `<table><thead><tr>${['layer','source','condition','bonus','main_rating','active'].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${config.bonus_system.rules.map(r=>`<tr><td>${t('layer.'+r.layer)}</td><td>${ruleSource(r)}</td><td>${esc(r.condition.op==='between'?r.condition.min+'–'+r.condition.max:r.condition.value===true?t('present'):String(r.condition.value??'—'))}</td><td>${esc(r.value)}</td><td>${t('main.'+r.target)}</td><td>${r.active?'✓':'—'}</td></tr>`).join('')}</tbody></table>`}
function formula(){const c=state.formula.config;app.innerHTML=heading('formula','formula_sub')+`<div class="panel"><span class="badge verified">${t('approved_active')} · ${c.mixes.athleticism?'V3':'V2'}</span><p>${t('version')} ${state.formula.version} · ${esc(c.name)}</p>${c.name.includes('V3.4')?`<button data-v34-rollback>${t('v34.rollback')}</button>`:''}${c.mixes.attack.ranked_pair?`<p>${t('v34.attack_pair')}</p>`:''}<table><thead><tr><th>${t('main_rating')}</th>${[1,2,3,4].map(w=>`<th>${w}</th>`).join('')}<th>10%</th></tr></thead><tbody>${mains.map(k=>`<tr><td>${t('main.'+k)}</td>${[...c.mixes[k].terms,...Array(Math.max(0,4-c.mixes[k].terms.length)).fill(null)].map(v=>v===null?'<td>—</td>':`<td>${v.ability==='height_rating'?t('height_rating'):abilityName(v.ability)} · ${Number(v.weight)*100}%</td>`).join('')}<td>${c.mixes[k].best_attribute?t('best'):t('formula.no_best')}</td></tr>`).join('')}</tbody></table><p>${t('weights')}: <span dir="ltr">${c.final.rank_weights.map(w=>Number(w)*100).join(' / ')}</span> · ${t('no_normalization')}</p><details><summary>${t('rules')} · ${c.bonus_system.rules.length}</summary>${rulesTable(c)}</details>${c.name.includes('V3.3')?`<button data-v33-rollback>${t('v33.rollback')}</button>`:''}${c.name.includes('V3.2')?`<button data-v32-rollback>${t('v32.rollback')}</button>`:''}${c.name.includes('V3.1')?`<button data-defense-rollback>${t('formula.rollback_defense')}</button>`:''}<button id="open-sim">${t('open_sim')}</button></div><div id="simulation"></div>`}
function simulation(){simConfig=JSON.parse(JSON.stringify(state.formula.config));document.querySelector('#simulation').innerHTML=`<div class="panel"><h2>${t('simulation')}</h2><p>${t('sim_hint')}</p><select id="sim-player" aria-label="${fieldName('full_name')}">${state.players.filter(p=>p.rating?.internal_overall).map(p=>`<option value="${p.id}">${esc(p.full_name)}</option>`).join('')}</select><form id="sim-form"><h3>${t('mixes')}</h3><table><tbody>${mains.map(k=>`<tr><td>${t('main.'+k)}</td>${simConfig.mixes[k].terms.map((v,i)=>`<td><select name="mix_${k}_${i}" aria-label="${t('main.'+k)} ${i+1}">${[...state.catalog.abilities,...(state.formula.config.ability_extensions||[]),{id:'height_rating'}].map(a=>`<option value="${a.id}" ${v.ability===a.id?'selected':''}>${a.id==='height_rating'?t('height_rating'):abilityName(a.id)}</option>`).join('')}</select><input type="number" name="weight_${k}_${i}" aria-label="${t('weights')} ${i+1}" min="0" max="200" step="0.1" value="${Number(v.weight)*100}">%</td>`).join('')}<td>${t('best')}<input name="best_${k}" aria-label="${t('best')} ${t('main.'+k)}" type="number" min="0" max="200" step="0.1" value="${Number(simConfig.mixes[k].best_attribute?.weight||0)*100}">%</td></tr>`).join('')}</tbody></table><h3>${t('weights')}</h3><div class="fields">${simConfig.final.rank_weights.map((w,i)=>`<div class="field"><label>${t('rank')} ${i+1}</label><input name="rank_${i}" type="number" min="0" max="200" step="0.1" value="${Number(w)*100}"></div>`).join('')}</div><details><summary>${t('rules')}</summary><table><tbody>${simConfig.bonus_system.rules.map((r,i)=>`<tr><td>${ruleSource(r)}</td><td><input aria-label="${t('active')} ${i+1}" type="checkbox" name="rule_active_${i}" ${r.active?'checked':''}></td><td><input aria-label="${t('bonus')} ${i+1}" type="number" step="0.25" name="rule_value_${i}" value="${esc(r.value)}"></td><td><select aria-label="${t('main_rating')} ${i+1}" name="rule_target_${i}">${mains.map(k=>`<option value="${k}" ${k===r.target?'selected':''}>${t('main.'+k)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></details></form><div class="actions"><button id="run-sim">${t('run_sim')}</button><button class="secondary" id="save-formula">${t('save_formula')}</button></div><div id="sim-result"></div></div>`}
function collectSimulation(){const c=JSON.parse(JSON.stringify(simConfig)),form=document.querySelector('#sim-form'),pct=k=>(Number(form.elements.namedItem(k).value)/100).toFixed(8);for(const [k,m]of Object.entries(c.mixes)){m.terms.forEach((v,i)=>{v.ability=form.elements.namedItem(`mix_${k}_${i}`).value;v.weight=pct(`weight_${k}_${i}`)});if(m.best_attribute){m.best_attribute.abilities=(m.best_attribute_policy==='all_terms'?m.terms:m.terms.slice(0,m.best_attribute_policy==='first_three'?3:2)).map(x=>x.ability);m.best_attribute.weight=pct('best_'+k)}}c.final.rank_weights=c.final.rank_weights.map((_,i)=>pct('rank_'+i));c.bonus_system.rules.forEach((r,i)=>{r.active=form.elements.namedItem('rule_active_'+i).checked;r.value=form.elements.namedItem('rule_value_'+i).value;r.target=form.elements.namedItem('rule_target_'+i).value});c.status='draft';return c}
function draftForm(values={}){document.querySelector('#draft-fields').innerHTML=fields.filter(k=>k!=='full_name').map(k=>fieldControl(k,values[k],{confidence:draftConfidence[k],suggested_value:draftSuggested[k]})).join('');updateCounters()}
async function drafts(){const list=await api('drafts');draftId=null;draftIdentity='';draftConfidence={};draftSuggested={};draftTouched=new Set();app.innerHTML=heading('drafts','draft_sub')+`<div class="panel"><h2>${t('new_draft')}</h2><p>${t('draft_hint')}</p><div class="filters"><input id="draft-name" aria-label="${fieldName('full_name')}" placeholder="${fieldName('full_name')}"><button id="suggest">${t('suggest')}</button></div><p id="suggestion-status" class="suggested-default" aria-live="polite"></p><form id="draft-form"><div class="fields" id="draft-fields"></div></form><div class="actions"><button id="save-draft">${t('save')}</button></div></div><div class="panel"><h2>${t('saved_drafts')}</h2>${list.length?list.map(d=>`<details><summary>${esc(d.name)} · ${date(d.updated_at)}</summary><p>${t('unverified')}</p><button class="secondary" data-load-draft="${d.id}">${t('continue_draft')}</button><div class="fields">${Object.entries(d.payload.fields).map(([k,v])=>`<div><label>${fieldName(k)}</label><p>${esc(shown(k,v))}</p></div>`).join('')}</div></details>`).join(''):`<p>${t('no_drafts')}</p>`}</div>`;draftForm()}
async function suggest(){const name=document.querySelector('#draft-name').value.trim();if(!name)return;if(draftIdentity&&draftIdentity!==name){draftId=null;draftTouched=new Set();draftConfidence={};draftSuggested={};draftForm({})}draftIdentity=name;const seq=++suggestSequence;document.querySelector('#suggestion-status').textContent=t('loading');const previous=readFields(document.querySelector('#draft-form')),r=await api('suggest',{name});if(seq!==suggestSequence||!document.querySelector('#draft-form'))return;const next={...previous};for(const [k,v]of Object.entries(r.fields)){if(!draftTouched.has(k)||previous[k]==null){next[k]=v;draftConfidence[k]=r.confidence[k];draftSuggested[k]=v}}draftForm(next);document.querySelector('#suggestion-status').textContent=t(r.message_key)}
let routeRevision=0;
async function route(){const revision=++routeRevision,destination=location.hash;try{modal.close();editing=null;cardPending=null;previewSequence++;suggestSequence++;const [view,id,mode]=(location.hash.slice(1).split('?')[0]||'dashboard').split('/');if(!state)return;if(view!=='drafts'&&typeof leaveDraftWorkspace==='function')leaveDraftWorkspace();if(!['drafts','abilities','club','country','clubs','countries','analytics','analytics-skill'].includes(view)&&!(view==='player'&&player(id))&&(state.compact||entityDataDirty)){app.innerHTML=`<p role="status">${t('loading')}</p>`;await reload(true);entityDataDirty=false}if(revision!==routeRevision||location.hash!==destination)return;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+(view==='player'?'players':view==='v3'?'formula':view)));if(view==='gk')await gkPage(id);else if(view==='analytics-skill')await analyticsSkillPage(decodeURIComponent(id||''));else if(view==='analytics')await analyticsPage(id);else if(view==='dashboard'){if(entityDataDirty){await reload(true);entityDataDirty=false}dashboard();await entityHome();}else if(view==='players')players();else if(view==='player'){if(state.compact||entityDataDirty){const fresh=await api('player/'+encodeURIComponent(id));const i=state.players.findIndex(p=>p.id===id);if(i<0)state.players.push(fresh);else state.players[i]=fresh;}card(id,false);}else if(view==='v3')dashboard();else if(view==='abilities')await entityPage('', '',id);else if(view==='country'||view==='club')await entityPage(view,decodeURIComponent(id||''));else if(view==='clubs'||view==='countries')await entityDirectory(view);else if(view==='formula'||view==='drafts')dashboard();else dashboard();if(revision===routeRevision){UI.enhance();restoreEntityOrigin()}}catch(e){if(revision===routeRevision){app.innerHTML=`<p role="alert">${esc(e.message)}</p>`;toast(e.message)}}}

