document.addEventListener('input',e=>{if(e.target.id==='search')filter();if(e.target.closest('#edit-form')){cardPending=null;previewSequence++;const save=document.querySelector('[data-save-card]');if(save)save.disabled=true}if(e.target.closest('#draft-form'))draftTouched.add(e.target.dataset.trait||e.target.name)});
document.addEventListener('change',e=>{const el=e.target;if(el.name?.startsWith('ability_')||el.name==='card_teamwork'||el.name==='card_form_ability')el.className=UI.AbilityTier(el.value);if(el.dataset.trait){const k=el.dataset.trait,form=el.closest('form');if(form.querySelectorAll(`[data-trait="${k}"]:checked`).length>state.validation.limits[k]){el.checked=false;toast(t('validation.'+k))}if(el.checked)form.elements.namedItem('known_'+k).checked=true;updateCounters(form)}if(el.name?.startsWith('known_')&&!el.checked){const k=el.name.slice(6);el.closest('form').querySelectorAll(`[data-trait="${k}"]`).forEach(x=>x.checked=false);updateCounters(el.closest('form'))}if(el.id==='ability-position'||el.id==='ability-style'){abilityPosition=document.querySelector('#ability-position').value;abilityStyle=document.querySelector('#ability-style').value;abilityRankings(el.dataset.abilityKey)}if(el.id.endsWith('-filter'))filter();if(el.id==='team'){teamIndex=Number(el.value);document.querySelector('#pitch').innerHTML=pitch()}if(editing&&el.closest('#edit-form'))cardPreview(editing);if(el.id==='draft-name'&&!document.querySelector('#phase5-draft'))suggest().catch(err=>toast(err.message))});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.hasAttribute('data-close'))modal.close();else if(b.dataset.quick)quick(b.dataset.quick);else if(b.dataset.quickEdit){modal.close();const hash='#player/'+b.dataset.quickEdit+'/edit';if(location.hash===hash)card(b.dataset.quickEdit,true);else location.hash=hash}else if(b.dataset.full){modal.close();location.hash='player/'+b.dataset.full}else if(b.dataset.edit)card(b.dataset.edit,b.dataset.mode==='edit');else if(b.dataset.cardPreview)await cardPreview(b.dataset.cardPreview);else if(b.dataset.saveCard){if(!cardPending||JSON.stringify(changes(b.dataset.saveCard))!==JSON.stringify(cardPending.body))throw Error(t('error.preview'));b.disabled=true;const saved=await api('save',{...cardPending.body,preview_token:cardPending.preview_token});acceptSavedPlayer(saved);const y=window.scrollY;card(b.dataset.saveCard);window.scrollTo(0,y);toast(t('saved'))}else if(b.hasAttribute('data-save')){b.disabled=true;const saved=await api('save',modalPending);acceptSavedPlayer(saved);modal.close();await route();toast(t('saved'))}else if(b.dataset.ability){const p=player(b.dataset.id);await modalPreview({player_id:p.id,revision:p.revision,fields:{},...(b.dataset.ability==='teamwork'?{abilities:{},teamwork:Number(document.getElementById('score-'+p.id).value),teamwork_revision:p.teamwork_revision}:{abilities:{[b.dataset.ability]:Number(document.getElementById('score-'+p.id).value)}}),confirm:[]})}else if(b.id==='open-sim')simulation();else if(b.id==='run-sim'){const r=await api('simulate',{player_id:document.querySelector('#sim-player').value,config:collectSimulation()});document.querySelector('#sim-result').innerHTML=`<h2>${t('overall')}: ${r.display_overall??'—'}</h2><p>${t('internal')}: ${r.internal_overall??'—'}</p>${ratings({rating:r})}<p>${t('sim_hint')}</p>`}else if(b.id==='save-formula'){await api('formula-draft',{config:collectSimulation()});toast(t('formula_saved'))}else if(b.id==='suggest')await suggest();else if(b.id==='save-draft'){const values=readFields(document.querySelector('#draft-form'));validateFrontend(values);await api('draft',{id:draftId,name:document.querySelector('#draft-name').value,fields:values,confidence:draftConfidence,suggested_values:draftSuggested});await drafts();toast(t('draft_saved'))}else if(b.dataset.loadDraft){const d=(await api('drafts')).find(x=>x.id===b.dataset.loadDraft);draftId=d.id;draftIdentity=d.name;draftConfidence=d.payload.confidence;draftSuggested=d.payload.suggested_values||{};draftTouched=new Set(Object.keys(d.payload.fields));document.querySelector('#draft-name').value=d.name;draftForm(d.payload.fields);toast(t('draft_loaded'))}}catch(error){b.disabled=false;toast(error.message)}});
window.addEventListener('hashchange',route);
async function setLocale(locale){await I18n.load(locale);shell();await route()}
function startWorkbench(){I18n.load('he').then(async()=>{shell();app.textContent=t('loading');await reload();await route()}).catch(()=>{app.textContent=t('error.generic')})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startWorkbench,{once:true});else startWorkbench();

document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.confirmAll){const r=await api('confirm-all-preview',changes(b.dataset.confirmAll));modalPending={...r.body,preview_token:r.preview_token};modal.innerHTML=`<h2>${t('confirm_all')}</h2><p>${t('confirm_all_question')}</p>${r.missing.length?`<p class="warning">${t('missing_critical')}: ${r.missing.map(fieldName).join(' · ')}</p>`:''}<button data-save-confirm-all>${t('confirm_all')}</button><button data-close class="secondary">${t('cancel')}</button>`;modal.showModal()}else if(b.hasAttribute('data-save-confirm-all')){b.disabled=true;const p=await api('save',modalPending);modal.close();await reload();card(p.id,true);const missing=state.critical.filter(k=>k==='abilities'?Object.keys(p.abilities).length!==20:p.fields[k]==null);toast(t('confirmed_all_saved')+(missing.length?' '+t('missing_critical')+': '+missing.map(fieldName).join(' · '):''));if(missing.length)document.querySelector('#edit-form').insertAdjacentHTML('afterbegin',`<p class="warning">${t('missing_critical')}: ${missing.map(fieldName).join(' · ')}</p>`)}}catch(error){b.disabled=false;toast(error.message)}});


// Entity lists inherit the server's exact Internal Overall order; no display-value sorting.
let entityOrigin=null;
function entityLink(kind,value){return value?`<a class="link" data-entity="${kind}" href="#${kind}/${encodeURIComponent(value)}">${UI.EntityIcon(kind,value)}<span>${esc(value)}</span></a>`:'—'}
function entityRanking(kind,value){
 const field=kind==='club'?'primary_club':'country',other=kind==='club'?'country':'primary_club';
 const ps=state.players.filter(p=>p.fields[field]===value);
 app.innerHTML=`<div class="title"><div><h1>${esc(value)}</h1><p>${t('entity_ranking')}</p></div><button data-entity-back>${t('back')}</button></div><div class="panel"><table><thead><tr>${['field.full_name','overall','field.position_id','field.playing_style','field.'+other].map(k=>`<th>${t(k)}</th>`).join('')}</tr></thead><tbody>${ps.map(p=>`<tr><td><button class="link" data-quick="${p.id}">${esc(p.full_name)}</button></td><td>${overall(p)}</td><td>${esc(shown('position_id',p.fields.position_id))}</td><td>${esc(shown('playing_style',p.fields.playing_style))}</td><td>${entityLink(other==='country'?'country':'club',p.fields[other])}</td></tr>`).join('')}</tbody></table>${!ps.length?`<p>${t('empty')}</p>`:''}</div>`;
}
function restoreEntityOrigin(){if(!entityOrigin||location.hash!==entityOrigin.hash)return;const origin=entityOrigin;entityOrigin=origin.parent;for(const [id,value]of origin.filters){const el=document.getElementById(id);if(el)el.value=value}if(document.querySelector('#search'))filter();if(origin.quick)quick(origin.quick);window.scrollTo(0,origin.scroll)}
document.addEventListener('click',e=>{const link=e.target.closest('a[data-entity]');if(link&&link.hash!==location.hash){entityOrigin={hash:location.hash,filters:[...document.querySelectorAll('.filters input[id],.filters select[id]')].map(el=>[el.id,el.value]),quick:modal.open?modal.dataset.playerId:null,scroll:window.scrollY,parent:entityOrigin};modal.close()}if(e.target.closest('[data-entity-back]')){if(entityOrigin)history.back();else location.hash='players'}});

function teamworkCard(p,edit){return `<div class="ability"><a href="#abilities/teamwork">${t('ability.teamwork')}</a>${edit?`<select name="card_teamwork" aria-label="${t('ability.teamwork')}"><option value="">${t('missing')}</option>${state.catalog.allowed_scores.map(v=>`<option value="${v}" ${v===p.teamwork?'selected':''}>${v}</option>`).join('')}</select>${UI.Metadata(p.teamwork_metadata,p.teamwork)}`:UI.AbilityValue(p.teamwork)}</div>`}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-defense-rollback]');if(!b)return;if(!confirm(t('formula.rollback_defense_confirm')))return;b.disabled=true;try{await api('rollback-defense',{});await reload(true);shell();await route();}catch(err){b.disabled=false;toast(err.message)}});

function formAbilityCard(p,edit){return `<div class="ability"><a href="#abilities/form_ability">${abilityName("form_ability")}</a>${edit?`<select name="card_form_ability" aria-label="${abilityName("form_ability")}"><option value="">${t("missing")}</option>${state.catalog.allowed_scores.map(v=>`<option value="${v}" ${v===p.form_ability?"selected":""}>${v}</option>`).join("")}</select>${UI.Metadata(p.form_ability_metadata,p.form_ability)}`:UI.AbilityValue(p.form_ability)}</div>`}

document.addEventListener('click',async e=>{const b=e.target.closest('[data-v32-rollback]');if(!b||!confirm(t('v32.rollback_confirm')))return;b.disabled=true;try{await api('rollback-v32',{});await reload(true);shell();await route()}catch(err){b.disabled=false;toast(err.message)}});

document.addEventListener('click',async e=>{const b=e.target.closest('[data-v33-rollback]');if(!b||!confirm(t('v33.rollback_confirm')))return;b.disabled=true;try{await api('rollback-v33',{});await reload(true);shell();await route()}catch(err){b.disabled=false;toast(err.message)}});

document.addEventListener("click",async e=>{const b=e.target.closest("[data-v34-rollback]");if(!b||!confirm(t("v34.rollback_confirm")))return;b.disabled=true;try{await api("rollback-v34",{});await reload(true);shell();await route()}catch(err){b.disabled=false;toast(err.message)}});

document.addEventListener('click',e=>{const b=e.target.closest('[data-portrait-page]');if(b){portraitPage=Number(b.dataset.portraitPage);filter(false);document.querySelector('#player-list').scrollIntoView({block:'start'});}});
document.addEventListener('change',e=>{if(e.target.matches('[data-portrait-size]')){portraitPageSize=Number(e.target.value);filter();}});

function playerHonours(id){const h=typeof HistoricalHonours!=="undefined"?HistoricalHonours[id]:null;if(!h)return "";const icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M8 4h8v5a4 4 0 0 1-8 0V4ZM8 6H5v2a4 4 0 0 0 4 4m7-6h3v2a4 4 0 0 1-4 4M12 13v5m-4 2h8m-6-2h4"/></svg>';return `<div class="player-honours" aria-label="תארים בקריירה">${[['Champions',h.ChampionsTitles],['Big 5 Titles',h.Big5Titles]].map(([label,value])=>`<span class="honour-stat" title="${esc(h.source)}">${icon}<span class="honour-label">${label}</span><b>${value}</b></span>`).join('')}</div>`;}

document.addEventListener('change',e=>{if(e.target.matches('[data-home-position-select]')){homePosition=e.target.value;document.querySelector('#home-position-host').innerHTML=homePositionList()}});

// Switch only the displayed lineup, using the same ranked rows as the former table.
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-home-team-step]');if(!button)return;
 homeTeamIndex=Math.max(0,Math.min(9,homeTeamIndex+Number(button.dataset.homeTeamStep)));
 const d=state.dashboard,team=homeTeamIndex===0?d.top11:{slots:d.position_order.map(position=>({position,player:d.position_top10[position][homeTeamIndex]||null}))};
 document.querySelector('#home-team-pitch').innerHTML=Formation.preview(team);
 document.querySelector('#home-team-counter').textContent=`הרכב ${homeTeamIndex+1} מתוך 10`;
 document.querySelectorAll('[data-home-team-step]').forEach(b=>b.disabled=Number(b.dataset.homeTeamStep)<0?homeTeamIndex===0:homeTeamIndex===9);
 const story=document.querySelector('.home-lineup-story>p');if(story)story.textContent=`הרכב ${homeTeamIndex+1} של המאגר · לפי הדירוג הקיים`;
 const stars=document.querySelector('.home-lineup-stars');if(stars)stars.innerHTML=team.slots.filter(s=>s.player).map(s=>s.player).sort((a,b)=>Number(player(b.id)?.rating?.internal_overall??b.rating.display_overall)-Number(player(a.id)?.rating?.internal_overall??a.rating.display_overall)).slice(0,3).map(p=>`<button data-quick="${esc(p.id)}">${UI.Portrait(p.id)}<span>${esc(p.full_name)}<small>${esc(p.fields?.primary_club||'')}</small></span>${UI.RatingBadge(overall(p))}</button>`).join('');
});
